@Test
public void testGetTime() throws IOException {
    final long currentTimeMillis = System.currentTimeMillis();
    final NTPUDPClient client = new NTPUDPClient();
    // timeout if response takes longer than 2 seconds
    client.setDefaultTimeout(Duration.ofSeconds(2));
    try {
        // Java 1.7: use InetAddress.getLoopbackAddress() instead
        final InetAddress addr = InetAddress.getByAddress("loopback", new byte[] { 127, 0, 0, 1 });
        final TimeInfo timeInfo = client.getTime(addr, server.getPort());
        Assert.assertNotNull(timeInfo);
        Assert.assertTrue(timeInfo.getReturnTime() >= currentTimeMillis);
        final NtpV3Packet message = timeInfo.getMessage();
        Assert.assertNotNull(message);
        final TimeStamp rcvTimeStamp = message.getReceiveTimeStamp();
        final TimeStamp xmitTimeStamp = message.getTransmitTimeStamp();
        Assert.assertTrue(xmitTimeStamp.compareTo(rcvTimeStamp) >= 0);
        final TimeStamp originateTimeStamp = message.getOriginateTimeStamp();
        Assert.assertNotNull(originateTimeStamp);
        Assert.assertTrue(originateTimeStamp.getTime() >= currentTimeMillis);
        Assert.assertEquals(NtpV3Packet.MODE_SERVER, message.getMode());
        // following assertions are specific to the SimpleNTPServer
        final TimeStamp referenceTimeStamp = message.getReferenceTimeStamp();
        Assert.assertNotNull(referenceTimeStamp);
        Assert.assertTrue(referenceTimeStamp.getTime() >= currentTimeMillis);
        Assert.assertEquals(NtpV3Packet.VERSION_3, message.getVersion());
        Assert.assertEquals(1, message.getStratum());
        Assert.assertEquals("LCL", NtpUtils.getReferenceClock(message));
    } finally {
        client.close();
    }
}

@Test
public void testCreate() {
    final NtpV3Packet message = new NtpV3Impl();
    // byte 0 [bit numbers 7-6]
    message.setLeapIndicator(0);
    // byte 0 [bit numbers 5-4]
    message.setVersion(NtpV3Packet.VERSION_3);
    // byte 0 [bit numbers 3-0]
    message.setMode(4);
    // byte 1
    message.setStratum(3);
    // byte 2
    message.setPoll(4);
    // byte 3
    message.setPrecision(-17);
    // bytes 4-7
    message.setRootDelay(100);
    // bytes 8-11
    message.setRootDispersion(3382);
    // byte 12-15
    message.setReferenceId(0x81531472);
    message.setReferenceTime(new TimeStamp(0xd552447fec1d6000L));
    message.setOriginateTimeStamp(new TimeStamp(0xd5524718ac49ba5eL));
    message.setReceiveTimeStamp(new TimeStamp(0xd55247194b6d9000L));
    message.setTransmitTime(new TimeStamp(0xd55247194b797000L));
    Assert.assertEquals(-17, message.getPrecision());
    Assert.assertEquals(4, message.getPoll());
    Assert.assertEquals(100, message.getRootDelay());
    Assert.assertEquals(3382, message.getRootDispersion());
    Assert.assertEquals(0x81531472, message.getReferenceId());
    Assert.assertNotNull(message.getReferenceTimeStamp());
    Assert.assertEquals("NTP", message.getType());
    Assert.assertEquals("Server", message.getModeName());
    Assert.assertEquals("129.83.20.114", message.getReferenceIdString());
    Assert.assertEquals(51, message.getRootDispersionInMillis());
    Assert.assertEquals(message.getRootDelay() / 65.536, message.getRootDelayInMillisDouble(), 1e-13);
    // this creates a new datagram
    final DatagramPacket dp = message.getDatagramPacket();
    Assert.assertNotNull(dp);
    // fixed 48-byte length
    Assert.assertEquals(48, dp.getLength());
    final NtpV3Packet message2 = new NtpV3Impl();
    final DatagramPacket dp2 = new DatagramPacket(ntpPacket, ntpPacket.length);
    message2.setDatagramPacket(dp2);
    Assert.assertEquals(message2, message);
    Assert.assertEquals(message2.hashCode(), message.hashCode());
    Assert.assertEquals(message2.toString(), message.toString());
}

@Test
public void testCreateAndSetByte0() {
    // LI + VN + Mode all part of first byte -- make sure set order does not matter
    final NtpV3Packet message = new NtpV3Impl();
    message.setLeapIndicator(2);
    message.setMode(4);
    message.setVersion(NtpV3Packet.VERSION_3);
    Assert.assertEquals(4, message.getMode());
    Assert.assertEquals(NtpV3Packet.VERSION_3, message.getVersion());
